{
  "name": "A2D数据采集模块",
  "name_en": "A2D DAQ Module",
  "manufacturer": "A2D",
  "description": "这是一款实验室用数据采集设备，具备模拟电压读取、温度测量和数字输入/输出功能，并带有板载指示灯与可配置通道。它适合用于传感器信号采集、基础电压监测、数字控制和通用实验自动化测试。",
  "description_en": "This is a laboratory data acquisition device with analog voltage readback, temperature measurement, and digital input/output capabilities, along with an onboard indicator LED and configurable channels. It is suitable for sensor readout, basic voltage monitoring, digital control, and general laboratory automation tasks.",
  "tag_hints": [
    "data acquisition",
    "analog voltage measurement",
    "digital I/O",
    "temperature measurement",
    "sensor readout",
    "lab automation",
    "DAQ module"
  ],
  "actions": [
    {
      "action_name": "auto-calibrate_pullup_v",
      "description": "校准上拉电压。",
      "description_en": "Calibrate the pull-up voltage."
    },
    {
      "action_name": "auto-conf_io",
      "description": "定义通道的数字输入/输出方向。",
      "description_en": "Define the digital input/output direction of a channel."
    },
    {
      "action_name": "auto-configure_from_dict",
      "description": "根据配置字典设置各个通道。",
      "description_en": "Configure each channel from a configuration dictionary."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化设备。",
      "description_en": "Initialize the device."
    },
    {
      "action_name": "auto-measure_temperature",
      "description": "测量指定通道的温度。",
      "description_en": "Measure the temperature on the specified channel."
    },
    {
      "action_name": "auto-measure_voltage",
      "description": "测量指定通道的电压。",
      "description_en": "Measure the voltage on the specified channel."
    },
    {
      "action_name": "auto-reset",
      "description": "复位设备。",
      "description_en": "Reset the device."
    },
    {
      "action_name": "auto-set_dig",
      "description": "设置指定通道的数字输出电平。",
      "description_en": "Set the digital output level of the specified channel."
    },
    {
      "action_name": "auto-set_led",
      "description": "设置板载指示灯状态。",
      "description_en": "Set the onboard LED state."
    },
    {
      "action_name": "auto-set_read_delay_ms",
      "description": "设置读取延迟时间（毫秒）。",
      "description_en": "Set the read delay in milliseconds."
    },
    {
      "action_name": "auto-get_pullup_v",
      "description": "获取上拉电压。",
      "description_en": "Get the pull-up voltage."
    },
    {
      "action_name": "auto-get_analog_mv",
      "description": "获取指定通道的模拟电压（毫伏）。",
      "description_en": "Get the analog voltage of the specified channel in millivolts."
    },
    {
      "action_name": "auto-get_analog_v",
      "description": "获取指定通道的模拟电压。",
      "description_en": "Get the analog voltage of the specified channel."
    },
    {
      "action_name": "auto-get_dig_in",
      "description": "获取指定通道的数字输入状态。",
      "description_en": "Get the digital input state of the specified channel."
    }
  ]
}

